pub(super) fn surnames(locale: &str) -> Option<&'static [&'static str]> {
    match locale {
        "en_US" => Some(EN_US_SURNAMES),
        "fr_FR" => Some(FR_FR_SURNAMES),
        "it_IT" => Some(IT_IT_SURNAMES),
        "ja_JP" => Some(JA_JP_SURNAMES),
        "ar_SA" => Some(AR_SA_SURNAMES),
        "de_DE" => Some(DE_DE_SURNAMES),
        "fa_IR" => Some(FA_IR_SURNAMES),
        "pt_BR" => Some(PT_BR_SURNAMES),
        "pt_PT" => Some(PT_PT_SURNAMES),
        "tr_TR" => Some(TR_TR_SURNAMES),
        "zh_CN" => Some(ZH_CN_SURNAMES),
        "zh_TW" => Some(ZH_TW_SURNAMES),
        "da_DK" => Some(nordic::DA_DK_LAST),
        "fi_FI" => Some(nordic::FI_FI_LAST),
        "sv_SE" => Some(nordic::SV_SE_LAST),
        "nb_NO" => Some(nordic::NB_NO_LAST),
        "en_GB" => Some(ukza_cy::EN_GB_SURNAMES),
        "en_ZA" => Some(ukza_cy::EN_ZA_SURNAMES),
        "el_CY" => Some(ukza_cy::EL_CY_SURNAMES),
        "fr_BE" => Some(romance::FR_BE_SURNAMES),
        "fr_CA" => Some(romance::FR_CA_SURNAMES),
        "fr_CH" => Some(romance::FR_CH_SURNAMES),
        "it_CH" => Some(romance::IT_CH_SURNAMES),
        "de_AT" => Some(company::DE_AT_SURNAMES),
        "de_CH" => Some(company::DE_CH_SURNAMES),
        "hu_HU" => Some(central::HU_HU_SURNAMES),
        "hr_HR" => Some(central::HR_HR_SURNAMES),
        "sl_SI" => Some(lt_sl_tr::SL_SI_SURNAMES),
        "ar_EG" => Some(company::EGYPTIAN_SURNAMES),
        "ar_JO" => Some(company::JORDANIAN_SURNAMES),
        "he_IL" => Some(west_asian::HE_IL_SURNAMES),
        "hy_AM" => Some(west_asian::HY_AM_SURNAMES),
        "ka_GE" => Some(KA_GE_SURNAMES),
        locale => iberian::surnames(locale),
    }
}

